/**
 * 💡 THOUGHT PROCESS:
 * One swatch renders ANOTHER preset entirely — deliberately does NOT read `LocalPulseColors.current`
 * / `MaterialTheme.colorScheme` (those reflect whichever theme the app is CURRENTLY running, not
 * the preset being previewed). `preset.toPulseColors()` is called directly so all ten swatches can
 * render side by side regardless of the app's active theme, matching the Token Contract's own
 * component spec ("Preset swatch card — background: preset's own surface... selected state:
 * accent.primary border + checkmark + dot").
 *
 * `remember(preset)` avoids re-resolving the same preset's colors on every recomposition — cheap,
 * but there's no reason to redo it when nothing about `preset` changed.
 */
@Composable
fun PresetSwatchCard(
    preset: MarketPulseTheme,
    isSelected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = remember(preset) { preset.toPulseColors() }
    val scheme = remember(preset) { preset.toColorScheme() }

    val cardPadding = dimensionResource(id = R.dimen.padding_medium)
    val cornerLarge = dimensionResource(id = R.dimen.corner_radius_card_large)
    val cornerCard = dimensionResource(id = R.dimen.corner_radius_card)
    val cornerChip = dimensionResource(id = R.dimen.corner_radius_chip)

    Card(
        onClick = onClick,
        modifier = modifier.fillMaxWidth(),
        shape = RoundedCornerShape(cornerLarge),
        colors = CardDefaults.cardColors(containerColor = scheme.surface),
        border = if (isSelected) BorderStroke(dimensionResource(id = R.dimen.border_medium), colors.accentPrimary) else null
    ) {
        Column(modifier = Modifier.padding(cardPadding)) {
            // --- Mini AI briefing card: the accent-tinted synthesis-layer preview ---
            Surface(
                color = colors.accentSurface,
                border = BorderStroke(dimensionResource(id = R.dimen.border_thin), colors.accentSurfaceBorder),
                shape = RoundedCornerShape(cornerCard)
            ) {
                Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_small))) {
                    Text(
                        text = stringResource(id = R.string.dashboard_technical_briefing),
                        style = MaterialTheme.typography.labelSmall.copy(fontWeight = FontWeight.Bold),
                        color = colors.accentPrimary
                    )
                    Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_tiny)))
                    Row(horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_tiny))) {
                        MiniSignalPill(
                            text = stringResource(id = R.string.settings_preset_sample_bullish),
                            textColor = colors.signalBullishText,
                            pillColor = colors.signalBullishPill,
                            cornerRadius = cornerChip
                        )
                        MiniSignalPill(
                            text = stringResource(id = R.string.settings_preset_sample_bearish),
                            textColor = colors.signalBearishText,
                            pillColor = colors.signalBearishPill,
                            cornerRadius = cornerChip
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_small)))

            // --- Preset name + selected checkmark ---
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = preset.displayName,
                    style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                    color = scheme.onSurface
                )
                if (isSelected) {
                    Icon(
                        painter = painterResource(id = R.drawable.ic_check),
                        contentDescription = stringResource(id = R.string.settings_preset_selected_content_description),
                        tint = colors.accentPrimary,
                        modifier = Modifier.size(dimensionResource(id = R.dimen.icon_size_small))
                    )
                }
            }

            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_tiny)))

            // --- Mode indicator (+ a filled dot next to the name when selected) ---
            Row(verticalAlignment = Alignment.CenterVertically) {
                if (isSelected) {
                    Box(
                        modifier = Modifier
                            .size(dimensionResource(id = R.dimen.bullet_size))
                            .background(color = colors.accentPrimary, shape = CircleShape)
                    )
                    Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_tiny)))
                }
                Text(
                    text = if (preset.isDark) {
                        stringResource(id = R.string.settings_preset_mode_dark)
                    } else {
                        stringResource(id = R.string.settings_preset_mode_light)
                    },
                    style = MaterialTheme.typography.labelSmall,
                    color = colors.onSurfaceMuted
                )
            }
        }
    }
}

@Composable
private fun MiniSignalPill(
    text: String,
    textColor: androidx.compose.ui.graphics.Color,
    pillColor: androidx.compose.ui.graphics.Color,
    cornerRadius: androidx.compose.ui.unit.Dp
) {
    Surface(color = pillColor, shape = RoundedCornerShape(cornerRadius)) {
        Text(
            text = text,
            style = MaterialTheme.typography.labelSmall.copy(fontWeight = FontWeight.Bold),
            color = textColor,
            modifier = Modifier.padding(
                horizontal = dimensionResource(id = R.dimen.padding_small),
                vertical = dimensionResource(id = R.dimen.padding_tiny)
            )
        )
    }
}

